/* prog26_wildcard_match.c
 *
 * Wild‑card matcher used in the original binary.
 * Supports the two wild‑cards:
 *   '?' – matches any single character
 *   '*' – matches any (possibly empty) sequence of characters
 *
 * Behaviour:
 *   - If the program is not given exactly two arguments, it prints "USAGE".
 *   - If either the pattern or the text is longer than 64 characters,
 *     it also prints "USAGE".
 *   - Otherwise it prints "MATCH" when the pattern matches the text,
 *     and "NO_MATCH" when it does not.
 *
 * The implementation follows the classic DP algorithm that the
 * decompiled binary uses (a 65×65 integer table, one extra row/column
 * for the empty prefix).
 */

#include <stdio.h>
#include <string.h>

#define MAXLEN 64          /* same limit used by the original binary */

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     * Argument handling – the original program prints "USAGE" for any
     * situation that does not provide a pattern and a text, or when the
     * inputs are too long.
     * ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t pat_len = strlen(pattern);
    size_t txt_len = strlen(text);

    if (pat_len > MAXLEN || txt_len > MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     * DP table: dp[i][j] == 1  ⇔  pattern[0..i‑1] matches text[0..j‑1]
     * The table size is (MAXLEN+1)×(MAXLEN+1) to match the layout used
     * by the original binary (row stride 0x104 = 65·4 bytes).
     * ----------------------------------------------------------------- */
    int dp[MAXLEN + 1][MAXLEN + 1] = {0};

    dp[0][0] = 1;                     /* empty pattern matches empty text */

    /* first column – pattern vs. empty text */
    for (size_t i = 1; i <= pat_len; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0]; /* '*' can match empty */
        else
            dp[i][0] = 0;
    }

    /* fill the rest of the table */
    for (size_t i = 1; i <= pat_len; ++i) {
        for (size_t j = 1; j <= txt_len; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*')
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            else if (pc == '?' || pc == tc)
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = 0;
        }
    }

    puts(dp[pat_len][txt_len] ? "MATCH" : "NO_MATCH");
    return 0;
}
